:root {
  color-scheme: light;
  --ink: #20312d;
  --muted: #64746d;
  --paper: #fffefa;
  --canvas: #f4f1ea;
  --line: #dce3dc;
  --green: #286b55;
  --mint: #e4f3e9;
  --gold: #f1c66d;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: var(--canvas);
  color: var(--ink);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
}
.card {
  width: min(100%, 820px);
  padding: clamp(22px, 5vw, 42px);
  background: var(--paper);
  border: 1px solid #e6e6dd;
  border-radius: 24px;
  box-shadow: 0 18px 50px #20312d12;
}
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 30px;
}
.eyebrow { margin: 0 0 7px; color: var(--green); font-size: 0.85rem; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(1.7rem, 5vw, 2.35rem); line-height: 1.12; letter-spacing: -.04em; }
.subtitle { margin: 9px 0 0; color: var(--muted); }
button {
  flex: 0 0 auto;
  min-height: 48px;
  padding: 0 20px;
  border: 0;
  border-radius: 12px;
  background: var(--green);
  color: white;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  transition: background .15s ease, transform .15s ease, box-shadow .15s ease;
}
button:hover { background: #1e5845; box-shadow: 0 5px 14px #286b5530; }
button:active { transform: translateY(2px); }
button:focus-visible, input:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
.grid-wrap { overflow-x: auto; padding: 4px 3px 8px; }
table { width: 100%; min-width: 600px; border-collapse: separate; border-spacing: 8px; text-align: center; }
th { color: var(--muted); font-size: .83rem; font-weight: 700; }
thead th { padding: 0 3px 4px; }
.corner { width: 50px; }
.sum-heading { color: var(--green); }
td { height: 62px; border: 1px solid var(--line); border-radius: 12px; background: #fbfcf8; font-weight: 700; }
td.input-cell { padding: 0; }
input[type="number"] {
  width: 100%;
  height: 60px;
  padding: 0 4px;
  border: 0;
  border-radius: 11px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: 1.25rem;
  font-weight: 700;
  text-align: center;
  appearance: textfield;
  -moz-appearance: textfield;
}
input::-webkit-inner-spin-button, input::-webkit-outer-spin-button { margin: 0; appearance: none; }
.row-sum, tfoot td { background: #f2f5ef; color: var(--green); font-size: 1.1rem; }
tbody tr.largest td { background: var(--mint); border-color: #a6cfb4; }
tbody tr.largest .row-sum { background: var(--green); color: white; border-color: var(--green); }
tfoot th { text-align: right; white-space: nowrap; }
tfoot td { height: 52px; }
tfoot .grand-total { background: var(--gold); color: #3d321c; font-size: 1.2rem; }
.status { margin: 18px 3px 0; color: var(--muted); font-size: .92rem; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 520px) {
  .card { padding: 22px 16px; border-radius: 18px; }
  .header { align-items: flex-start; flex-direction: column; margin-bottom: 20px; }
  button { width: 100%; }
  table { min-width: 570px; border-spacing: 6px; }
}

const body = document.querySelector('#grid-body');
const cells = [];

for (let row = 0; row < 4; row += 1) {
  const tr = document.createElement('tr');
  const heading = document.createElement('th');
  heading.scope = 'row';
  heading.textContent = `Row ${row + 1}`;
  tr.append(heading);
  cells[row] = [];

  for (let col = 0; col < 4; col += 1) {
    const td = document.createElement('td');
    td.className = 'input-cell';
    const input = document.createElement('input');
    input.type = 'number';
    input.min = '0';
    input.max = '999';
    input.step = '1';
    input.value = '0';
    input.setAttribute('aria-label', `Row ${row + 1}, column ${col + 1}`);
    input.addEventListener('input', updateTotals);
    td.append(input);
    tr.append(td);
    cells[row][col] = input;
  }

  const sum = document.createElement('td');
  sum.className = 'row-sum';
  sum.id = `row-sum-${row}`;
  sum.setAttribute('aria-label', `Row ${row + 1} sum`);
  sum.textContent = '0';
  tr.append(sum);
  body.append(tr);
}

function valueAt(row, col) {
  const value = Number.parseInt(cells[row][col].value, 10);
  return Number.isFinite(value) ? value : 0;
}

function updateTotals() {
  const rowSums = [];
  const colSums = [0, 0, 0, 0];
  let grandTotal = 0;

  for (let row = 0; row < 4; row += 1) {
    let sum = 0;
    for (let col = 0; col < 4; col += 1) {
      const value = valueAt(row, col);
      sum += value;
      colSums[col] += value;
    }
    rowSums.push(sum);
    grandTotal += sum;
    document.querySelector(`#row-sum-${row}`).textContent = sum;
  }

  colSums.forEach((sum, col) => {
    document.querySelector(`#col-sum-${col}`).textContent = sum;
  });
  document.querySelector('#grand-total').textContent = grandTotal;

  const largest = Math.max(...rowSums);
  [...body.rows].forEach((tr, row) => {
    tr.classList.toggle('largest', rowSums[row] === largest);
  });
  document.querySelector('#status').textContent = `The highlighted row${rowSums.filter(sum => sum === largest).length > 1 ? 's are' : ' is'} the largest${rowSums.filter(sum => sum === largest).length > 1 ? ' (ties are all highlighted)' : ''}.`;
}

document.querySelector('#randomize').addEventListener('click', () => {
  cells.flat().forEach(input => {
    input.value = String(Math.floor(Math.random() * 9) + 1);
  });
  updateTotals();
});

updateTotals();
